static public str editConditionValue(Name _formStringControlValue, str _previousValue,  boolean _appendValueOnLookUp, GUPPricingAttributeLink _priceAttributeLink)
{
    str     ret = _previousValue;
    boolean isRefRecIdValue = _priceAttributeLink.pricingAttribute().isRefRecIdValue();

    if (strLen(_formStringControlValue) == 0)
    {
        ret = '';
    }
    else if (isRefRecIdValue)
    {
        ret = GUPPricingAttributeConditionValueHelper::editConditionValueIsRefRecIdValue(_formStringControlValue, _previousValue, _appendValueOnLookUp, _priceAttributeLink);
    }
    else if (!isRefRecIdValue)
    {
        ret = GUPPricingAttributeConditionValueHelper::editConditionValueIsNotRefRecIdValue(_formStringControlValue, _previousValue, _appendValueOnLookUp, _priceAttributeLink);
    }

    return ret;
}

static private str editConditionValueIsRefRecIdValue(Name _formStringControlValue, str _previousValue, boolean _appendValueOnLookUp, GUPPricingAttributeLink _priceAttributeLink)
{
    //When a pricing attribute is RefRecId - formStringControlValue.replaceOnLookup(true) i.e. it will not include previous value
    str ret = _previousValue;

    if (!_appendValueOnLookup)
    {
        ret = _formStringControlValue;

        if (!_priceAttributeLink.pricingAttribute().validate(_formStringControlValue))
        {
            //User selects from LookUp or edit the textbox manauly (manual value needs to be validated)
            ret = _previousValue;
        }
    }
    else
    {
        int previousValuelen = strLen(_previousValue);

        if (previousValuelen == 0)
        {
            //if previous value is empty assign new value
            ret = _formStringControlValue;
        }
        else if (previousValuelen > 0)
        {
            //User selects from LookUp or edit the textbox manauly (manual value needs to be validated)
            if (_priceAttributeLink.pricingAttribute().validate(_formStringControlValue))
            {
                //When it's a RefRecID, _formStringControlValue contains only the new selected value from the lookup.
                //Parse string to find new values to add to the conditionValue
                boolean valueAlreadyAdded = false;
                ListEnumerator existingValuesListEnumerator = strSplit(_previousValue, ',').getEnumerator();
                while (existingValuesListEnumerator.moveNext())
                {
                    if (existingValuesListEnumerator.current() == _formStringControlValue)
                    {
                        valueAlreadyAdded = true;
                        break;
                    }
                }
                if (!valueAlreadyAdded)
                {
                    ret +=  ',' + _formStringControlValue;
                }
            }
            else if (!_priceAttributeLink.pricingAttribute().validate(_formStringControlValue))
            {
                ret = _previousValue;
            }               
        }
    }

    return ret;
}

static private str editConditionValueIsNotRefRecIdValue(Name _formStringControlValue, str _previousValue, boolean _appendValueOnLookUp, GUPPricingAttributeLink _priceAttributeLink)
{
    //When a pricing attribute is not RefRecId - formStringControlValue.replaceOnLookup(false) i.e. it will include previous value.
    str ret = _previousValue;

    if (!_appendValueOnLookup)
    {
        ret = _formStringControlValue;
    }
    else
    {
        int previousValuelen = strLen(_previousValue);

        if (previousValuelen == 0)
        {
            //if previous value is empty assign new value
            ret = _formStringControlValue;
        }
        else if (previousValuelen > 0)
        {
            boolean valueAlreadyAdded = false;
            //If _formStringControlValue start exaclty like the previousValue, it means it's an append from the Lookup
            int findIfItStartsWithPreviousValue = strScan(_formStringControlValue, _previousValue, 1, 1);

            if (findIfItStartsWithPreviousValue == 1)
            {
                //Parse string to find new values to add to the conditionValue
                str newValue = strReplace(_formStringControlValue, _previousValue, '');
                ListEnumerator existingValuesListEnumerator = strSplit(_previousValue, ',').getEnumerator();
                while (existingValuesListEnumerator.moveNext())
                {
                    if (existingValuesListEnumerator.current() == newValue)
                    {
                        valueAlreadyAdded = true;
                        break;
                    }
                }
                if (!valueAlreadyAdded)
                {
                    ret +=  ',' + newValue;
                }
            }
            else
            {
                //if not, it means the user edit the textbox manually.
                //Clean ConditionValue and add all the values in _formStringControlValue.
                ret = '';
                ListEnumerator newValuesListEnumerator = strSplit(_formStringControlValue, ',').getEnumerator();
                boolean bFirst=true;
                while (newValuesListEnumerator.moveNext())
                {
                    if (bFirst)
                    {
                        bFirst = false;
                    }
                    else
                    {
                        ret += ',';
                    }
                    ret += newValuesListEnumerator.current();
                }
            }                
        }
    }

    return ret;
}

static public void setPricingAttributeValueLookUpOptions(FormStringControl _formStringControl, GUPPricingAttributeLink _priceAttributeLink, boolean _appendValueOnLookUp)
{
    _formStringControl.replaceOnLookup(!_appendValueOnLookUp || (_priceAttributeLink.pricingAttribute().isRefRecIdValue()));

    //Set LookUpOnly depending on the attribute types, and AppendCheckBox
    if (_priceAttributeLink.AttributeProviderClassId)
    {
        // Prohibit customized input for 'fixed value' or 'GUPPricingRuleCondition' price attribute.
        GUPIPricingAttribute priceAttribute = _priceAttributeLink.pricingAttribute();
        if (priceAttribute.getFixedAllowedValueEnumId() != GUPAbstractPricingAttribute::ENUM_ID_NOT_EXIST
                || priceAttribute.getDataType() == AttributeDataType::Reference)
        {
            _formStringControl.lookupOnly(true);
        }
        else
        {
            _formStringControl.lookupOnly(false);
        }
    }
    else
    {
        _formStringControl.lookupOnly(false);
    }
}
